async def _add_sellers(self, records: list[dict[str, Any]], today: date) -> None:
    orders: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        if record.get("tracking_id") and record.get("items"):
            orders.setdefault(record["order_id"], []).append(record)
    self._seller_details = {
        order: cached for order, cached in self._seller_details.items()
        if order in orders
    }
    fetched = False
    ordered = sorted(
        orders,
        key=lambda order: not any(
            (record.get("carrier_code") or "").upper() in {"DPD", "DHL"}
            for record in orders[order]
        ),
    )
    for order in ordered:
        shipments = orders[order]
        checked, sellers = self._seller_details.get(order, (date.min, {}))
        titles = {tuple(record["items"]) for record in shipments}
        missing = any(not sellers.get(items) for items in titles)
        if missing and checked < today and not fetched:
            fetched = True
            try:
                query = URL.build(query={"orderID": order}).query_string
                async with asyncio.timeout(12):
                    page = await self._fetch_page(
                        "/gp/your-account/order-details?" + query,
                        headers={
                            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                            "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36",
                            "Accept-Language": "de-DE,de;q=0.9,en;q=0.8",
                        },
                    )
            except (AmazonApiError, aiohttp.ClientError, TimeoutError):
                self._seller_details[order] = (today, sellers)
            else:
                sellers = {
                    **sellers,
                    **{items: sellers_for_items(page, items) for items in titles
                       if not sellers.get(items)},
                }
                self._seller_details[order] = (today, sellers)
        for record in shipments:
            if seller := sellers.get(tuple(record["items"])):
                record["order_seller"] = seller

